I'm so sorry to have disturbed you. Have a good day. Goodbye.locals {
  outage_group_name = "${var.project_name}-${var.environment}-outage"
}

resource "aws_sns_topic" "outage" {
  name = local.outage_group_name
}

resource "aws_sns_topic_subscription" "outage_email" {
  count     = length(var.outage_email_list)
  topic_arn = aws_sns_topic.outage.arn
  protocol  = "email"
  endpoint  = var.outage_email_list[count.index]
}

resource "aws_cloudwatch_metric_alarm" "outage" {
  alarm_name          = "${local.outage_group_name}-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = "1"
  metric_name         = "HealthyHostCount"
  namespace           = "AWS/ApplicationELB"
  period              = "60"
  statistic           = "Average"
  threshold           = "1"
  alarm_description   = "This metric monitors the health of the target group and triggers an alarm if there are no healthy hosts."
  alarm_actions       = [aws_sns_topic.outage.arn]

  dimensions = {
    TargetGroup  = var.alb_target_group_arn_suffix
    LoadBalancer = var.alb_arn_suffix
  }
}
